+  color: #020617;
+  background: var(--focus);
+  font-weight: 700;
+  transition: transform 160ms ease;
+}
+
+.skip-link:focus {
+  transform: translateY(0);
+  outline: 3px solid transparent;
+}
+
+.page-shell {
+  display: grid;
+  min-height: 100vh;
+  place-items: center;
+  padding: 2rem 1rem;
+}
+
+.support-card {
+  width: min(100%, 42rem);
+  border: 1px solid var(--border);
+  border-radius: 1.5rem;
+  padding: clamp(1.5rem, 5vw, 3rem);
+  background:
+    linear-gradient(180deg, rgba(255, 255, 255, 0.06), transparent),
+    var(--panel);
+  box-shadow: 0 1.5rem 4rem rgba(0, 0, 0, 0.4);
+}
+
+.intro {
+  margin-bottom: 2rem;
+}
+
+.eyebrow {
+  margin: 0 0 0.5rem;
+  color: var(--accent);
+  font-size: 0.82rem;
+  font-weight: 800;
+  letter-spacing: 0.14em;
+  text-transform: uppercase;
+}
+
+h1 {
+  margin: 0;
+  font-size: clamp(2rem, 7vw, 3.5rem);
+  line-height: 1.05;
+}
+
+.intro p:last-child {
+  max-width: 34rem;
+  margin: 1rem 0 0;
+  color: var(--muted);
+}
+
+.contact-form {
+  display: grid;
+  gap: 1.25rem;
+}
+
+.form-field {
+  display: grid;
+  gap: 0.45rem;
+}
+
+label {
+  color: var(--text);
+  font-weight: 700;
+}
+
+.optional,
+.helper-text {
+  color: var(--muted);
+  font-weight: 500;
+}
+
+input {
+  width: 100%;
+  border: 1px solid var(--border);
+  border-radius: 0.9rem;
+  padding: 0.85rem 1rem;
+  color: var(--text);
+  background: var(--field-bg);
+  font: inherit;
+  transition:
+    border-color 160ms ease,
+    box-shadow 160ms ease,
+    background 160ms ease;
+}
+
+input:hover {
+  border-color: #64748b;
+  background: var(--panel-strong);
+}
+
+input:focus {
+  border-color: var(--focus);
+  outline: 3px solid transparent;
+  box-shadow: 0 0 0 3px rgba(253, 230, 138, 0.45);
+}
+
+input[aria-invalid="true"] {
+  border-color: var(--danger);
+}
+
+.helper-text {
+  margin: 0;
+  font-size: 0.95rem;
+}
+
+button {
+  justify-self: start;
+  border: 0;
+  border-radius: 999px;
+  padding: 0.9rem 1.35rem;
+  color: #03111c;
+  background: linear-gradient(135deg, var(--accent), var(--accent-strong));
+  font: inherit;
+  font-weight: 800;
+  cursor: pointer;
+  box-shadow: 0 1rem 2rem rgba(56, 189, 248, 0.2);
+  transition:
+    transform 160ms ease,
+    box-shadow 160ms ease;
+}
+
+button:hover {
+  transform: translateY(-1px);
+  box-shadow: 0 1.25rem 2.35rem rgba(56, 189, 248, 0.28);
+}
+
+button:focus {
+  outline: 3px solid transparent;
+  box-shadow:
+    0 0 0 3px var(--focus),
+    0 1.25rem 2.35rem rgba(56, 189, 248, 0.28);
+}
+
+button:active {
+  transform: translateY(0);
+}
+
+@media (max-width: 26rem) {
+  .page-shell {
+    padding-inline: 0.75rem;
+  }
+
+  .support-card {
+    border-radius: 1rem;
+  }
+
+  button {
+    width: 100%;
+  }
+}
+
+@media (forced-colors: active) {
+  .support-card,
+  input,
+  button {
+    border: 1px solid ButtonBorder;
+  }
+
+  input:focus,
+  button:focus {
+    outline: 3px solid Highlight;
+    box-shadow: none;
+  }
+}
*** Add File: script.js
+const form = document.querySelector(".contact-form");
+const fields = Array.from(form.querySelectorAll("input"));
+
+function updateInvalidState(field) {
+  field.setAttribute("aria-invalid", field.validity.valid ? "false" : "true");
+}
+
+fields.forEach((field) => {
+  field.addEventListener("input", () => updateInvalidState(field));
+  field.addEventListener("blur", () => {
+    if (field.value.trim() !== "") {
+      updateInvalidState(field);
+    }
+  });
+});
+
+form.addEventListener("submit", (event) => {
+  event.preventDefault();
+
+  fields.forEach(updateInvalidState);
+
+  const firstInvalidField = fields.find((field) => !field.validity.valid);
+
+  if (firstInvalidField) {
+    firstInvalidField.focus();
+    return;
+  }
+
+  form.reset();
+  fields.forEach((field) => field.setAttribute("aria-invalid", "false"));
+});
*** End Patch
