+const form = document.querySelector(".contact-form");
+const fields = Array.from(form.querySelectorAll("input"));
+
+function updateInvalidState(field) {
+  field.setAttribute("aria-invalid", field.validity.valid ? "false" : "true");
+}
+
+fields.forEach((field) => {
+  field.addEventListener("input", () => updateInvalidState(field));
+  field.addEventListener("blur", () => {
+    if (field.value.trim() !== "") {
+      updateInvalidState(field);
+    }
+  });
+});
+
+form.addEventListener("submit", (event) => {
+  event.preventDefault();
+
+  fields.forEach(updateInvalidState);
+
+  const firstInvalidField = fields.find((field) => !field.validity.valid);
+
+  if (firstInvalidField) {
+    firstInvalidField.focus();
+    return;
+  }
+
+  form.reset();
+  fields.forEach((field) => field.setAttribute("aria-invalid", "false"));
+});
+

